# BoltzApiError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class BoltzApiError(Exception):
    pass

_UniffiTempBoltzApiError = BoltzApiError

class BoltzApiError:  # type: ignore
    class InvalidPublicKey(_UniffiTempBoltzApiError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "BoltzApiError.InvalidPublicKey({})".format(str(self))
    _UniffiTempBoltzApiError.InvalidPublicKey = InvalidPublicKey # type: ignore
    class ApiError(_UniffiTempBoltzApiError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "BoltzApiError.ApiError({})".format(str(self))
    _UniffiTempBoltzApiError.ApiError = ApiError # type: ignore
    class Generic(_UniffiTempBoltzApiError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "BoltzApiError.Generic({})".format(str(self))
    _UniffiTempBoltzApiError.Generic = Generic # type: ignore

BoltzApiError = _UniffiTempBoltzApiError # type: ignore
del _UniffiTempBoltzApiError


class _UniffiConverterTypeBoltzApiError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return BoltzApiError.InvalidPublicKey(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return BoltzApiError.ApiError(
                _UniffiConverterString.read(buf),
            )
        if variant == 3:
            return BoltzApiError.Generic(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, BoltzApiError.InvalidPublicKey):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, BoltzApiError.ApiError):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, BoltzApiError.Generic):
            _UniffiConverterString.check_lower(value._values[0])
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, BoltzApiError.InvalidPublicKey):
            buf.write_i32(1)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, BoltzApiError.ApiError):
            buf.write_i32(2)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, BoltzApiError.Generic):
            buf.write_i32(3)
            _UniffiConverterString.write(value._values[0], buf)





class Chain:
    def __init__(self):
        raise RuntimeError("Chain cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class BITCOIN:
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Chain.BITCOIN{self._values!r}"

        def __eq__(self, other):
            if not other.is_BITCOIN():
                return False
            return self._values == other._values
    class LIQUID:
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __str__(self):
            return f"Chain.LIQUID{self._values!r}"

        def __eq__(self, other):
            if not other.is_LIQUID():
                return False
            return self._values == other._values
    

    # For each variant, we have `is_NAME` and `is_name` methods for easily checking
    # whether an instance is that variant.
    def is_BITCOIN(self) -> bool:
        return isinstance(self, Chain.BITCOIN)
    def is_bitcoin(self) -> bool:
        return isinstance(self, Chain.BITCOIN)
    def is_LIQUID(self) -> bool:
        return isinstance(self, Chain.LIQUID)
    def is_liquid(self) -> bool:
        return isinstance(self, Chain.LIQUID)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
Chain.BITCOIN = type("Chain.BITCOIN", (Chain.BITCOIN, Chain,), {})  # type: ignore
Chain.LIQUID = type("Chain.LIQUID", (Chain.LIQUID, Chain,), {})  # type: ignore




class _UniffiConverterTypeChain(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return Chain.BITCOIN(
                _UniffiConverterTypeBitcoinChain.read(buf),
            )
        if variant == 2:
            return Chain.LIQUID(
                _UniffiConverterTypeLiquidChain.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_BITCOIN():
            _UniffiConverterTypeBitcoinChain.check_lower(value._values[0])
            return
        if value.is_LIQUID():
            _UniffiConverterTypeLiquidChain.check_lower(value._values[0])
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_BITCOIN():
            buf.write_i32(1)
            _UniffiConverterTypeBitcoinChain.write(value._values[0], buf)
        if value.is_LIQUID():
            buf.write_i32(2)
            _UniffiConverterTypeLiquidChain.write(value._values[0], buf)







